":"ops_api_native_reconciliation_part_041","filename":"20261013145745_ops_api_native_reconciliation_part_041.sql","sha256":"adeaa18864e423bf2682d3c20f7f65456c07f2aa2ab1cddd4bbbb621bff4afc3","md5":"b5541daf4cab3ee95ce83a9bcc52cdfa","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145749","name":"ops_api_native_reconciliation_part_042","filename":"20261013145749_ops_api_native_reconciliation_part_042.sql","sha256":"b5a02adf27139b8fb43b5dd798b2fae4c13b09743a1253dc003b2e0699da2659","md5":"12954a05756cfb74da40721d63f8dd39","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145751","name":"ops_api_native_reconciliation_part_043","filename":"20261013145751_ops_api_native_reconciliation_part_043.sql","sha256":"8663b52d94cb7d9ce737eb889512ec292aa7b80edfe35bfbb5f08dcd05715cf5","md5":"43407484316eedc9b0feab782fb18fc9","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145755","name":"ops_api_native_reconciliation_part_044","filename":"20261013145755_ops_api_native_reconciliation_part_044.sql","sha256":"a132a15cfd09ddc3f37910ae7c09534caf0a612356d4c2e5facfd488c286224b","md5":"ffbb986109a6e2fd9294598cf897c997","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145759","name":"ops_api_native_reconciliation_part_045","filename":"20261013145759_ops_api_native_reconciliation_part_045.sql","sha256":"8f48d11241e15d56e42f8e5a6fc2b672e005213253533c67e3669ab3e6807464","md5":"bb6483c4901f736dbcbc1883f89d3c0c","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145818","name":"ops_api_native_reconciliation_part_046","filename":"20261013145818_ops_api_native_reconciliation_part_046.sql","sha256":"e385532ddfe2e9b37bf9412d8bdbf57bada59ba8e0d64afaa01edcc0add0cda8","md5":"495e720be2757b4c5e0de3d9b620a3f8","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145821","name":"ops_api_native_reconciliation_part_047","filename":"20261013145821_ops_api_native_reconciliation_part_047.sql","sha256":"eb217d1f51c0e7c51d57ce2055c6893000c54d7695d0ce13d5410a9677809869","md5":"69095058006543a737ee153039507bd0","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145824","name":"ops_api_native_reconciliation_part_048","filename":"20261013145824_ops_api_native_reconciliation_part_048.sql","sha256":"aabbbec1d7e4b64f406a177f2f945b3be16ce08523074b360a07d5351e6932fc","md5":"dd8a06321ddea89d578b815ada16fb45","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145827","name":"ops_api_native_reconciliation_part_049","filename":"20261013145827_ops_api_native_reconciliation_part_049.sql","sha256":"2f27c8310026a2a331c62793fe676be47971920c3f34132a2f5c110da9100a30","md5":"a5d5b9894439dcbbbe006ceaaabe523f","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145831","name":"ops_api_native_reconciliation_part_050","filename":"20261013145831_ops_api_native_reconciliation_part_050.sql","sha256":"31b956ad477e84d6010f2af6053d22d10a89a1f6336c208d1d81d96b7d5c35b6","md5":"d913e2b7b9bb69d6242013958d9b0e8b","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013145835","name":"ops_api_native_reconciliation_part_051","filename":"20261013145835_ops_api_native_reconciliation_part_051.sql","sha256":"ae937b54cfbbd42683b468ac72d3dedb26dc5241be07999c4a59bf7dda0346cd","md5":"1d20570d33025a28590fede0e9af5c41","receipt":"quality/audits/2026-10-12-ops-api-contracts/native-staged-source-apply-receipt.json","qualification":"source_byte_transport_only"},{"version":"20261013151412","name":"ops_api_market_actor_normalizers","filename":"20261013151412_ops_api_market_actor_normalizers.sql","sha256":"2a5a5523fafaa80b416c5c489a8018a4640a910c66dc5486569751898c60b5cd","md5":"395b6d34c40d5da833b08e173da4f96a","receipt":"quality/audits/2026-10-12-ops-api-contracts/generated-actor-normalizers-native-apply-receipt.json","qualification":"bounded_input_only"}],"catalog":{"columns":[{"name":"receipt_id","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"project_ref","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"applied_ledger_version","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"applied_ledger_name","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"canonical_filename","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"source_file_sha256","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"recorded_input_md5","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"recorded_input_sha256","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"receipt_kind","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"source_file_git_commit","type":"text","default":null,"notnull":false,"identity":"","generated":""},{"name":"source_observation_head","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"current_source_sha256","type":"text","default":null,"notnull":false,"identity":"","generated":""},{"name":"current_source_git_commit","type":"text","default":null,"notnull":false,"identity":"","generated":""},{"name":"observed_at","type":"timestamp with time zone","default":null,"notnull":true,"identity":"","generated":""},{"name":"registered_at","type":"timestamp with time zone","default":"clock_timestamp()","notnull":true,"identity":"","generated":""},{"name":"effect_scope","type":"text","default":null,"notnull":true,"identity":"","generated":""},{"name":"effect_verified","type":"boolean","default":"false","notnull":true,"identity":"","generated":""},{"name":"effect_evidence","type":"jsonb","default":"'{}'::jsonb","notnull":true,"identity":"","generated":""}],"relation":{"acl":"{postgres=arwdDxtm/postgres,service_role=r/postgres}","owner":"postgres","rowsecurity":true,"forcerowsecurity":true},"triggers":[{"name":"ops_migration_provenance_no_truncate","enabled":"O","definition":"CREATE TRIGGER ops_migration_provenance_no_truncate BEFORE TRUNCATE ON public.ops_migration_provenance_receipts FOR EACH STATEMENT EXECUTE FUNCTION ops_reject_migration_provenance_mutation_v1()"},{"name":"ops_migration_provenance_no_update_delete","enabled":"O","definition":"CREATE TRIGGER ops_migration_provenance_no_update_delete BEFORE DELETE OR UPDATE ON public.ops_migration_provenance_receipts FOR EACH ROW EXECUTE FUNCTION ops_reject_migration_provenance_mutation_v1()"}],"constraints":[{"name":"ops_migration_provenance_rece_applied_ledger_version_applie_key","type":"u","validated":true,"definition":"UNIQUE (applied_ledger_version, applied_ledger_name, canonical_filename, receipt_kind, source_file_sha256, observed_at)"},{"name":"ops_migration_provenance_receip_current_source_git_commit_check","type":"c","validated":true,"definition":"CHECK (current_source_git_commit IS NULL OR current_source_git_commit ~ '^[a-f0-9]{40}$'::text)"},{"name":"ops_migration_provenance_receipts_applied_ledger_version_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (applied_ledger_version) REFERENCES supabase_migrations.schema_migrations(version) ON DELETE RESTRICT"},{"name":"ops_migration_provenance_receipts_check","type":"c","validated":true,"definition":"CHECK (receipt_kind = 'exact_input'::text AND source_file_sha256 = recorded_input_sha256 AND current_source_sha256 IS NULL OR receipt_kind = 'historical_source_lineage'::text AND source_file_git_commit IS NOT NULL AND current_source_sha256 IS NOT NULL AND current_source_git_commit IS NOT NULL AND effect_scope = 'historical_lineage_only'::text)"},{"name":"ops_migration_provenance_receipts_check1","type":"c","validated":true,"definition":"CHECK (effect_verified = (effect_scope = 'current_native_schema'::text))"},{"name":"ops_migration_provenance_receipts_check2","type":"c","validated":true,"definition":"CHECK (effect_scope <> 'current_native_schema'::text OR receipt_kind = 'exact_input'::text AND jsonb_typeof(effect_evidence -> 'native_snapshot'::text) = 'object'::text)"},{"name":"ops_migration_provenance_receipts_current_source_sha256_check","type":"c","validated":true,"definition":"CHECK (current_source_sha256 IS NULL OR current_source_sha256 ~ '^[a-f0-9]{64}$'::text)"},{"name":"ops_migration_provenance_receipts_effect_evidence_check","type":"c","validated":true,"definition":"CHECK (jsonb_typeof(effect_evidence) = 'object'::text)"},{"name":"ops_migration_provenance_receipts_effect_scope_check","type":"c","validated":true,"definition":"CHECK (effect_scope = ANY (ARRAY['input_only'::text, 'historical_lineage_only'::text, 'current_native_schema'::text]))"},{"name":"ops_migration_provenance_receipts_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (receipt_id)"},{"name":"ops_migration_provenance_receipts_project_ref_check","type":"c","validated":true,"definition":"CHECK (project_ref = 'piidsfebjqjmnepdpnas'::text)"},{"name":"ops_migration_provenance_receipts_receipt_kind_check","type":"c","validated":true,"definition":"CHECK (receipt_kind = ANY (ARRAY['exact_input'::text, 'historical_source_lineage'::text]))"},{"name":"ops_migration_provenance_receipts_recorded_input_md5_check","type":"c","validated":true,"definition":"CHECK (recorded_input_md5 ~ '^[a-f0-9]{32}$'::text)"},{"name":"ops_migration_provenance_receipts_recorded_input_sha256_check","type":"c","validated":true,"definition":"CHECK (recorded_input_sha256 ~ '^[a-f0-9]{64}$'::text)"},{"name":"ops_migration_provenance_receipts_source_file_git_commit_check","type":"c","validated":true,"definition":"CHECK (source_file_git_commit IS NULL OR source_file_git_commit ~ '^[a-f0-9]{40}$'::text)"},{"name":"ops_migration_provenance_receipts_source_file_sha256_check","type":"c","validated":true,"definition":"CHECK (source_file_sha256 ~ '^[a-f0-9]{64}$'::text)"},{"name":"ops_migration_provenance_receipts_source_observation_head_check","type":"c","validated":true,"definition":"CHECK (source_observation_head ~ '^[a-f0-9]{40}$'::text)"}]}}$exact_next_inputs$::jsonb;
 expected jsonb;
 expected_evidence jsonb;
 expected_row jsonb;
 existing public.ops_migration_provenance_receipts%ROWTYPE;
 actual_catalog jsonb;
 before_rows jsonb;
 before_ledger jsonb;
 after_ledger jsonb;
 before_count bigint;
 inserted_count bigint:=0;
 observed_at timestamptz:=(context->>'observed_at')::timestamptz;
 receipt_id_value text;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'ops_next_input_receipts_owner_required';END IF;
 IF jsonb_array_length(context->'inputs')<>56 OR context->>'commit'!~'^[a-f0-9]{40}$' THEN
  RAISE EXCEPTION 'ops_next_input_receipts_exact_committed_set_required';END IF;
 SELECT jsonb_build_object('relation',(SELECT jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rowsecurity',c.relrowsecurity,'forcerowsecurity',c.relforcerowsecurity)FROM pg_class c WHERE c.oid='public.ops_migration_provenance_receipts'::regclass),'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))ORDER BY a.attnum)FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.ops_migration_provenance_receipts'::regclass AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated)ORDER BY c.conname)FROM pg_constraint c WHERE c.conrelid='public.ops_migration_provenance_receipts'::regclass),'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))ORDER BY t.tgname)FROM pg_trigger t WHERE t.tgrelid='public.ops_migration_provenance_receipts'::regclass AND NOT t.tgisinternal)) INTO actual_catalog;
 IF actual_catalog IS DISTINCT FROM context->'catalog' THEN
  RAISE EXCEPTION 'ops_next_input_receipts_registry_catalog_changed_requires_review';END IF;
 SELECT coalesce(jsonb_object_agg(r.receipt_id,to_jsonb(r)),'{}'::jsonb),count(*)
  INTO before_rows,before_count FROM public.ops_migration_provenance_receipts r;
 SELECT coalesce(jsonb_object_agg(l.version,encode(sha256(convert_to(to_jsonb(l)::text,'UTF8')),'hex')),'{}'::jsonb)
  INTO before_ledger FROM supabase_migrations.schema_migrations l;
 FOR expected IN SELECT value FROM jsonb_array_elements(context->'inputs') LOOP
  IF NOT EXISTS(SELECT FROM supabase_migrations.schema_migrations l
   WHERE l.version=expected->>'version' AND l.name=expected->>'name'
    AND cardinality(l.statements)=1
    AND md5(array_to_string(l.statements,E'\n'))=expected->>'md5'
    AND encode(sha256(convert_to(array_to_string(l.statements,E'\n'),'UTF8')),'hex')=expected->>'sha256') THEN
   RAISE EXCEPTION 'ops_next_recorded_input_drift:%',expected->>'version';END IF;
  expected_evidence:=jsonb_build_object('source_input_only',true,
   'source_proof','Real pushed source commit bytes exactly match independently observed recorded SQL SHA256 and MD5.',
   'bounded_native_receipt',expected->>'receipt','input_qualification',expected->>'qualification',
   'qualification','Exact recorded input bytes only. No full module effects, API lifecycle readiness, historical mapping or pending semantic installation is certified.');
  receipt_id_value:='ops-api-5e63abe4:'||(expected->>'version')||':exact-input';
  expected_row:=jsonb_build_object('receipt_id',receipt_id_value,'project_ref','piidsfebjqjmnepdpnas',
   'applied_ledger_version',expected->>'version','applied_ledger_name',expected->>'name',
   'canonical_filename',expected->>'filename','source_file_sha256',expected->>'sha256',
   'recorded_input_md5',expected->>'md5','recorded_input_sha256',expected->>'sha256',
   'receipt_kind','exact_input','source_file_git_commit',context->>'commit',
   'source_observation_head',context->>'commit','current_source_sha256',NULL,
   'current_source_git_commit',NULL,'observed_at',observed_at,'registered_at',NULL,
   'effect_scope','input_only','effect_verified',false,'effect_evidence',expected_evidence);
  SELECT * INTO existing FROM public.ops_migration_provenance_receipts WHERE receipt_id=receipt_id_value;
  IF NOT FOUND THEN
   IF EXISTS(SELECT FROM public.ops_migration_provenance_receipts r WHERE r.applied_ledger_version=expected->>'version') THEN
    RAISE EXCEPTION 'ops_next_input_already_registered_under_other_id:%',expected->>'version';END IF;
   INSERT INTO public.ops_migration_provenance_receipts(receipt_id,project_ref,applied_ledger_version,applied_ledger_name,
    canonical_filename,source_file_sha256,recorded_input_md5,recorded_input_sha256,receipt_kind,
    source_file_git_commit,source_observation_head,current_source_sha256,current_source_git_commit,
    observed_at,effect_scope,effect_verified,effect_evidence)
    SELECT receipt_id_value,'piidsfebjqjmnepdpnas',expected->>'version',expected->>'name',expected->>'filename',
     expected->>'sha256',expected->>'md5',expected->>'sha256','exact_input',context->>'commit',context->>'commit',
     NULL,NULL,observed_at,'input_only',false,expected_evidence RETURNING * INTO existing;
   inserted_count:=inserted_count+1;
  END IF;
  -- registered_at is the genuine server-generated insertion instant. Every
  -- other field is exact; the entire prior row, including that clock, is retained.
  IF existing.registered_at IS NULL OR existing.registered_at<observed_at
   OR to_jsonb(existing) IS DISTINCT FROM(expected_row||jsonb_build_object('registered_at',existing.registered_at)) THEN
   RAISE EXCEPTION 'ops_next_input_receipt_full_row_replay_drift:%',expected->>'version';END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_each(before_rows) old WHERE NOT EXISTS(
   SELECT FROM public.ops_migration_provenance_receipts r WHERE r.receipt_id=old.key AND to_jsonb(r)=old.value))
   OR (SELECT count(*) FROM public.ops_migration_provenance_receipts)<>before_count+inserted_count THEN
  RAISE EXCEPTION 'ops_next_input_receipts_existing_full_rows_must_remain_unchanged';END IF;
 SELECT coalesce(jsonb_object_agg(l.version,encode(sha256(convert_to(to_jsonb(l)::text,'UTF8')),'hex')),'{}'::jsonb)
  INTO after_ledger FROM supabase_migrations.schema_migrations l;
 IF after_ledger IS DISTINCT FROM before_ledger THEN
  RAISE EXCEPTION 'ops_next_input_receipts_historical_ledger_must_remain_exact';END IF;
END;
$next_reviewed_input_receipts$;
COMMIT;
